-- Refresh school dataset 241126 (schools: 249, majors: 38, major_links: 4887, verified scholarships: 253, BEA state living costs: 51, reference fees: True, media: 996, field_evidence: 8832).
-- UC-103: never overwrites is_active or rows edited by a Moderator (last_edited_by_user_id IS NOT NULL).
-- #14: removes invalid scholarships (university_id IS NULL / kind = 'external' / study_level <> 'undergraduate') and stale auto-imported rows superseded by this dataset.
SET LOCAL standard_conforming_strings = on;
SET LOCAL lock_timeout = '10s';

-- 1. Ensure all 249 schools exist (new rows default to is_active = TRUE; existing rows keep is_active & Moderator edits)
ON CONFLICT (code) DO NOTHING;

-- 2. Overlay verified 241126 values onto non-Moderator-edited universities and undergraduate university_offerings
CREATE TEMP TABLE _refresh_school_241126 (code text PRIMARY KEY, university_data jsonb NOT NULL, offering_data jsonb NOT NULL) ON COMMIT DROP;

WITH incoming AS (
    SELECT t.id, jsonb_populate_record(NULL::app.universities, to_jsonb(t) || s.university_data) AS row_data
    FROM _refresh_school_241126 s
    JOIN app.universities t ON t.code = s.code
    WHERE t.last_edited_by_user_id IS NULL
)
UPDATE app.universities target
SET name = (incoming.row_data).name,
    city = (incoming.row_data).city,
    state = (incoming.row_data).state,
    website = (incoming.row_data).website,
    control = (incoming.row_data).control,
    acceptance_rate = (incoming.row_data).acceptance_rate,
    international_student_count = (incoming.row_data).international_student_count,
    is_ivy = (incoming.row_data).is_ivy,
    updated_at = CURRENT_TIMESTAMP
FROM incoming
WHERE target.id = incoming.id
  AND target.last_edited_by_user_id IS NULL
  AND ROW(target.name, target.city, target.state, target.website, target.control, target.acceptance_rate, target.international_student_count, target.is_ivy) IS DISTINCT FROM ROW((incoming.row_data).name, (incoming.row_data).city, (incoming.row_data).state, (incoming.row_data).website, (incoming.row_data).control, (incoming.row_data).acceptance_rate, (incoming.row_data).international_student_count, (incoming.row_data).is_ivy);

SELECT gen_random_uuid(), u.id, 'undergraduate', CURRENT_TIMESTAMP
FROM _refresh_school_241126 s
JOIN app.universities u ON u.code = s.code
ON CONFLICT (university_id, study_level) DO NOTHING;

WITH incoming AS (
    SELECT t.id, jsonb_populate_record(NULL::app.university_offerings, to_jsonb(t) || s.offering_data || CASE WHEN s.offering_data ? 'deadlines_json' THEN jsonb_build_object('deadlines_json', COALESCE(NULLIF(t.deadlines_json, 'null'::jsonb), '{}'::jsonb) || (s.offering_data->'deadlines_json')) ELSE '{}'::jsonb END) AS row_data
    FROM _refresh_school_241126 s
    JOIN app.universities u ON u.code = s.code
    JOIN app.university_offerings t ON t.university_id = u.id AND t.study_level = 'undergraduate'
    WHERE t.last_edited_by_user_id IS NULL
)
UPDATE app.university_offerings target
SET academic_year = (incoming.row_data).academic_year,
    tuition_usd = (incoming.row_data).tuition_usd,
    fees_usd = (incoming.row_data).fees_usd,
    living_usd = (incoming.row_data).living_usd,
    other_expenses_usd = (incoming.row_data).other_expenses_usd,
    health_insurance_usd = (incoming.row_data).health_insurance_usd,
    application_fee_usd = (incoming.row_data).application_fee_usd,
    act_policy = (incoming.row_data).act_policy,
    act_submit_pct = (incoming.row_data).act_submit_pct,
    tuition_in_state_usd = (incoming.row_data).tuition_in_state_usd,
    min_gpa4 = (incoming.row_data).min_gpa4,
    min_ielts = (incoming.row_data).min_ielts,
    min_toefl = (incoming.row_data).min_toefl,
    min_duolingo = (incoming.row_data).min_duolingo,
    avg_gpa4 = (incoming.row_data).avg_gpa4,
    avg_gpa_weighted = (incoming.row_data).avg_gpa_weighted,
    gpa_scale_type = (incoming.row_data).gpa_scale_type,
    sat25 = (incoming.row_data).sat25,
    sat75 = (incoming.row_data).sat75,
    act25 = (incoming.row_data).act25,
    act75 = (incoming.row_data).act75,
    sat_policy = (incoming.row_data).sat_policy,
    sat_submit_pct = (incoming.row_data).sat_submit_pct,
    gpa_submit_pct = (incoming.row_data).gpa_submit_pct,
    gpa_pct_4_0 = (incoming.row_data).gpa_pct_4_0,
    gpa_pct_375_399 = (incoming.row_data).gpa_pct_375_399,
    gpa_pct_350_374 = (incoming.row_data).gpa_pct_350_374,
    gpa_pct_325_349 = (incoming.row_data).gpa_pct_325_349,
    gpa_pct_300_324 = (incoming.row_data).gpa_pct_300_324,
    gpa_pct_250_299 = (incoming.row_data).gpa_pct_250_299,
    gpa_pct_below_250 = (incoming.row_data).gpa_pct_below_250,
    c7_gpa_importance = (incoming.row_data).c7_gpa_importance,
    c7_test_importance = (incoming.row_data).c7_test_importance,
    c7_ec_importance = (incoming.row_data).c7_ec_importance,
    applicants_total = (incoming.row_data).applicants_total,
    admitted_total = (incoming.row_data).admitted_total,
    intl_applicants = (incoming.row_data).intl_applicants,
    intl_admitted = (incoming.row_data).intl_admitted,
    intl_acceptance_rate = (incoming.row_data).intl_acceptance_rate,
    intl_aid_policy = (incoming.row_data).intl_aid_policy,
    intl_aid_avg_usd = (incoming.row_data).intl_aid_avg_usd,
    intl_aid_recipients = (incoming.row_data).intl_aid_recipients,
    retention_rate_1yr = (incoming.row_data).retention_rate_1yr,
    grad_rate_6yr = (incoming.row_data).grad_rate_6yr,
    fy_on_campus_pct = (incoming.row_data).fy_on_campus_pct,
    ug_on_campus_pct = (incoming.row_data).ug_on_campus_pct,
    housing_types = (incoming.row_data).housing_types,
    intl_housing = (incoming.row_data).intl_housing,
    housing_only_usd = (incoming.row_data).housing_only_usd,
    housing_deposit_usd = (incoming.row_data).housing_deposit_usd,
    student_faculty_ratio = (incoming.row_data).student_faculty_ratio,
    activities = (incoming.row_data).activities,
    campus_setting = (incoming.row_data).campus_setting,
    deadlines_json = (incoming.row_data).deadlines_json,
    source_url = (incoming.row_data).source_url,
    retrieved_at = (incoming.row_data).retrieved_at,
    source_reliability = (incoming.row_data).source_reliability,
    updated_at = CURRENT_TIMESTAMP
FROM incoming
WHERE target.id = incoming.id
  AND target.last_edited_by_user_id IS NULL
  AND ROW(target.academic_year, target.tuition_usd, target.fees_usd, target.living_usd, target.other_expenses_usd, target.health_insurance_usd, target.application_fee_usd, target.act_policy, target.act_submit_pct, target.tuition_in_state_usd, target.min_gpa4, target.min_ielts, target.min_toefl, target.min_duolingo, target.avg_gpa4, target.avg_gpa_weighted, target.gpa_scale_type, target.sat25, target.sat75, target.act25, target.act75, target.sat_policy, target.sat_submit_pct, target.gpa_submit_pct, target.gpa_pct_4_0, target.gpa_pct_375_399, target.gpa_pct_350_374, target.gpa_pct_325_349, target.gpa_pct_300_324, target.gpa_pct_250_299, target.gpa_pct_below_250, target.c7_gpa_importance, target.c7_test_importance, target.c7_ec_importance, target.applicants_total, target.admitted_total, target.intl_applicants, target.intl_admitted, target.intl_acceptance_rate, target.intl_aid_policy, target.intl_aid_avg_usd, target.intl_aid_recipients, target.retention_rate_1yr, target.grad_rate_6yr, target.fy_on_campus_pct, target.ug_on_campus_pct, target.housing_types, target.intl_housing, target.housing_only_usd, target.housing_deposit_usd, target.student_faculty_ratio, target.activities, target.campus_setting, target.deadlines_json, target.source_url, target.retrieved_at, target.source_reliability) IS DISTINCT FROM ROW((incoming.row_data).academic_year, (incoming.row_data).tuition_usd, (incoming.row_data).fees_usd, (incoming.row_data).living_usd, (incoming.row_data).other_expenses_usd, (incoming.row_data).health_insurance_usd, (incoming.row_data).application_fee_usd, (incoming.row_data).act_policy, (incoming.row_data).act_submit_pct, (incoming.row_data).tuition_in_state_usd, (incoming.row_data).min_gpa4, (incoming.row_data).min_ielts, (incoming.row_data).min_toefl, (incoming.row_data).min_duolingo, (incoming.row_data).avg_gpa4, (incoming.row_data).avg_gpa_weighted, (incoming.row_data).gpa_scale_type, (incoming.row_data).sat25, (incoming.row_data).sat75, (incoming.row_data).act25, (incoming.row_data).act75, (incoming.row_data).sat_policy, (incoming.row_data).sat_submit_pct, (incoming.row_data).gpa_submit_pct, (incoming.row_data).gpa_pct_4_0, (incoming.row_data).gpa_pct_375_399, (incoming.row_data).gpa_pct_350_374, (incoming.row_data).gpa_pct_325_349, (incoming.row_data).gpa_pct_300_324, (incoming.row_data).gpa_pct_250_299, (incoming.row_data).gpa_pct_below_250, (incoming.row_data).c7_gpa_importance, (incoming.row_data).c7_test_importance, (incoming.row_data).c7_ec_importance, (incoming.row_data).applicants_total, (incoming.row_data).admitted_total, (incoming.row_data).intl_applicants, (incoming.row_data).intl_admitted, (incoming.row_data).intl_acceptance_rate, (incoming.row_data).intl_aid_policy, (incoming.row_data).intl_aid_avg_usd, (incoming.row_data).intl_aid_recipients, (incoming.row_data).retention_rate_1yr, (incoming.row_data).grad_rate_6yr, (incoming.row_data).fy_on_campus_pct, (incoming.row_data).ug_on_campus_pct, (incoming.row_data).housing_types, (incoming.row_data).intl_housing, (incoming.row_data).housing_only_usd, (incoming.row_data).housing_deposit_usd, (incoming.row_data).student_faculty_ratio, (incoming.row_data).activities, (incoming.row_data).campus_setting, (incoming.row_data).deadlines_json, (incoming.row_data).source_url, (incoming.row_data).retrieved_at, (incoming.row_data).source_reliability);

-- 3. Upsert CIP 2020 majors (keep curated name_vi/aliases/is_popular) & sync offering-major links for non-Moderator-edited offerings
ON CONFLICT (name) DO UPDATE SET cip_code = EXCLUDED.cip_code, updated_at = CURRENT_TIMESTAMP WHERE app.majors.cip_code IS DISTINCT FROM EXCLUDED.cip_code;

CREATE TEMP TABLE _refresh_majors_241126 (code text NOT NULL, major_name text NOT NULL, is_stem boolean NOT NULL, is_verified boolean NOT NULL) ON COMMIT DROP;
DELETE FROM app.university_offering_majors uom
USING app.university_offerings o, app.universities u
WHERE uom.university_offering_id = o.id
  AND o.university_id = u.id
  AND o.study_level = 'undergraduate'
  AND o.last_edited_by_user_id IS NULL
  AND EXISTS (SELECT 1 FROM _refresh_school_241126 s WHERE s.code = u.code)
  AND NOT EXISTS (
      SELECT 1
      FROM _refresh_majors_241126 r
      JOIN app.majors m ON m.name = r.major_name
      WHERE r.code = u.code AND m.id = uom.major_id
  );
SELECT o.id, m.id, r.is_stem, r.is_verified
FROM _refresh_majors_241126 r
JOIN app.universities u ON u.code = r.code
JOIN app.university_offerings o ON o.university_id = u.id AND o.study_level = 'undergraduate'
JOIN app.majors m ON m.name = r.major_name
WHERE o.last_edited_by_user_id IS NULL
ON CONFLICT (university_offering_id, major_id) DO UPDATE
SET is_stem = EXCLUDED.is_stem, is_verified = EXCLUDED.is_verified
WHERE app.university_offering_majors.is_stem IS DISTINCT FROM EXCLUDED.is_stem
   OR app.university_offering_majors.is_verified IS DISTINCT FROM EXCLUDED.is_verified;

-- 4. Clean invalid/stale scholarships (#14) & upsert 253 verified undergraduate scholarships (UC-103: preserve is_active & Moderator edits)
CREATE TEMP TABLE _refresh_scholarships_241126 (
    id uuid NOT NULL,
    code text NOT NULL,
    name varchar(256) NOT NULL,
    provider varchar(256),
    study_level varchar(32) NOT NULL,
    amount_usd numeric(12,2),
    coverage_type varchar(32),
    min_gpa4 numeric(3,2),
    min_ielts numeric(3,1),
    deadline date,
    eligibility_notes varchar(2000),
    source_url varchar(512),
    retrieved_at date,
    source_reliability varchar(16),
    is_active boolean NOT NULL,
    kind varchar(32),
    amount_type varchar(32),
    amount_min_usd numeric(12,2),
    amount_max_usd numeric(12,2),
    duration_years integer,
    renewable boolean,
    renewal_criteria varchar(1000),
    intl_eligible boolean,
    vn_eligible boolean,
    need_based boolean,
    merit_based boolean,
    min_sat integer,
    min_act integer,
    min_toefl numeric(5,1),
    min_duolingo numeric(5,1),
    major_restriction varchar(500),
    application_method varchar(32),
    apply_url varchar(512),
    PRIMARY KEY (code, name)
) ON COMMIT DROP;

DELETE FROM app.scholarships
WHERE university_id IS NULL
   OR kind = 'external'
   OR study_level IS DISTINCT FROM 'undergraduate';
DELETE FROM app.scholarships target
WHERE target.last_edited_by_user_id IS NULL
  AND NOT EXISTS (
      SELECT 1
      FROM _refresh_scholarships_241126 s
      JOIN app.universities u ON u.code = s.code
      WHERE u.id = target.university_id AND s.name = target.name
  );
UPDATE app.scholarships target
SET provider = s.provider,
    study_level = s.study_level,
    amount_usd = s.amount_usd,
    coverage_type = s.coverage_type,
    min_gpa4 = s.min_gpa4,
    min_ielts = s.min_ielts,
    deadline = s.deadline,
    eligibility_notes = s.eligibility_notes,
    source_url = s.source_url,
    retrieved_at = s.retrieved_at,
    source_reliability = s.source_reliability,
    kind = s.kind,
    amount_type = s.amount_type,
    amount_min_usd = s.amount_min_usd,
    amount_max_usd = s.amount_max_usd,
    duration_years = s.duration_years,
    renewable = s.renewable,
    renewal_criteria = s.renewal_criteria,
    intl_eligible = s.intl_eligible,
    vn_eligible = s.vn_eligible,
    need_based = s.need_based,
    merit_based = s.merit_based,
    min_sat = s.min_sat,
    min_act = s.min_act,
    min_toefl = s.min_toefl,
    min_duolingo = s.min_duolingo,
    major_restriction = s.major_restriction,
    application_method = s.application_method,
    apply_url = s.apply_url,
    updated_at = CURRENT_TIMESTAMP
FROM _refresh_scholarships_241126 s
JOIN app.universities u ON u.code = s.code
WHERE target.university_id = u.id
  AND target.name = s.name
  AND target.last_edited_by_user_id IS NULL
  AND ROW(target.provider, target.study_level, target.amount_usd, target.coverage_type, target.min_gpa4, target.min_ielts, target.deadline, target.eligibility_notes, target.source_url, target.retrieved_at, target.source_reliability, target.kind, target.amount_type, target.amount_min_usd, target.amount_max_usd, target.duration_years, target.renewable, target.renewal_criteria, target.intl_eligible, target.vn_eligible, target.need_based, target.merit_based, target.min_sat, target.min_act, target.min_toefl, target.min_duolingo, target.major_restriction, target.application_method, target.apply_url) IS DISTINCT FROM ROW(s.provider, s.study_level, s.amount_usd, s.coverage_type, s.min_gpa4, s.min_ielts, s.deadline, s.eligibility_notes, s.source_url, s.retrieved_at, s.source_reliability, s.kind, s.amount_type, s.amount_min_usd, s.amount_max_usd, s.duration_years, s.renewable, s.renewal_criteria, s.intl_eligible, s.vn_eligible, s.need_based, s.merit_based, s.min_sat, s.min_act, s.min_toefl, s.min_duolingo, s.major_restriction, s.application_method, s.apply_url);
SELECT s.id, u.id, s.is_active, s.name, s.provider, s.study_level, s.amount_usd, s.coverage_type, s.min_gpa4, s.min_ielts, s.deadline, s.eligibility_notes, s.source_url, s.retrieved_at, s.source_reliability, s.kind, s.amount_type, s.amount_min_usd, s.amount_max_usd, s.duration_years, s.renewable, s.renewal_criteria, s.intl_eligible, s.vn_eligible, s.need_based, s.merit_based, s.min_sat, s.min_act, s.min_toefl, s.min_duolingo, s.major_restriction, s.application_method, s.apply_url, CURRENT_TIMESTAMP
FROM _refresh_scholarships_241126 s
JOIN app.universities u ON u.code = s.code
WHERE NOT EXISTS (
    SELECT 1 FROM app.scholarships existing
    WHERE existing.university_id = u.id AND existing.name = s.name
)
ON CONFLICT (id) DO NOTHING;

-- 5. Upsert 51 BEA SARPP state living cost indices (UC-28)
ON CONFLICT (state_code, year) DO UPDATE
SET index_all_items = EXCLUDED.index_all_items,
    index_housing_rents = EXCLUDED.index_housing_rents,
    index_goods = EXCLUDED.index_goods,
    index_other_services = EXCLUDED.index_other_services,
    source_url = EXCLUDED.source_url,
    retrieved_at = EXCLUDED.retrieved_at,
    updated_at = CURRENT_TIMESTAMP
WHERE ROW(app.state_living_costs.index_all_items, app.state_living_costs.index_housing_rents, app.state_living_costs.index_goods, app.state_living_costs.index_other_services, app.state_living_costs.source_url, app.state_living_costs.retrieved_at)
   IS DISTINCT FROM ROW(EXCLUDED.index_all_items, EXCLUDED.index_housing_rents, EXCLUDED.index_goods, EXCLUDED.index_other_services, EXCLUDED.source_url, EXCLUDED.retrieved_at);

-- 6. Upsert F-1 visa MRV and SEVIS I-901 reference fees (UC-26)
ON CONFLICT (key) DO UPDATE
SET value_json = EXCLUDED.value_json,
    description = EXCLUDED.description,
    updated_at = CURRENT_TIMESTAMP
WHERE app.app_settings.value_json IS DISTINCT FROM EXCLUDED.value_json
   OR app.app_settings.description IS DISTINCT FROM EXCLUDED.description;

-- 7. Sync 996 university media rows & Commons attribution (license/author/source_page_url)
CREATE TEMP TABLE _refresh_media_241126 (id uuid NOT NULL, code text NOT NULL, type varchar(32) NOT NULL, url varchar(1000) NOT NULL, display_order integer NOT NULL, license varchar(100), author varchar(300), source_page_url varchar(1000), PRIMARY KEY (code, url)) ON COMMIT DROP;
UPDATE app.media target
SET license = COALESCE(target.license, m.license),
    author = COALESCE(target.author, m.author),
    source_page_url = COALESCE(target.source_page_url, m.source_page_url),
    updated_at = CURRENT_TIMESTAMP
FROM _refresh_media_241126 m
JOIN app.universities u ON u.code = m.code
WHERE target.entity_type = 'University'
  AND target.entity_id = u.id
  AND target.url = m.url
  AND ROW(target.license, target.author, target.source_page_url)
      IS DISTINCT FROM ROW(COALESCE(target.license, m.license), COALESCE(target.author, m.author), COALESCE(target.source_page_url, m.source_page_url));
SELECT m.id, 'University', u.id, m.type, m.url, m.display_order, m.license, m.author, m.source_page_url, CURRENT_TIMESTAMP
FROM _refresh_media_241126 m
JOIN app.universities u ON u.code = m.code
WHERE NOT EXISTS (
    SELECT 1 FROM app.media existing
    WHERE existing.entity_type = 'University' AND existing.entity_id = u.id AND existing.url = m.url
)
ON CONFLICT (id) DO NOTHING;

-- 8. Replace dataset field_evidence with 8832 clean verified/derived rows (UC-21 group provenance & #14 stale cleanup)
CREATE TEMP TABLE _refresh_evidence_241126 (id uuid PRIMARY KEY, code text NOT NULL, field_name varchar(64) NOT NULL, field_value text, source_url varchar(512), source_section varchar(64), extracted_quote text NOT NULL, verified_by varchar(128) NOT NULL, status varchar(32) NOT NULL) ON COMMIT DROP;
DELETE FROM app.field_evidence fe
USING app.universities u
WHERE fe.university_id = u.id
  AND u.last_edited_by_user_id IS NULL
  AND NOT EXISTS (
    SELECT 1 FROM app.university_offerings o
    WHERE o.university_id = u.id AND o.study_level = 'undergraduate' AND o.last_edited_by_user_id IS NOT NULL
  )
  AND EXISTS (SELECT 1 FROM _refresh_school_241126 s WHERE s.code = u.code)
  AND NOT EXISTS (SELECT 1 FROM _refresh_evidence_241126 e WHERE e.id = fe.id);
SELECT e.id, u.id, e.field_name, e.field_value, e.source_url, e.source_section, e.extracted_quote, e.verified_by, e.status, CURRENT_TIMESTAMP
FROM _refresh_evidence_241126 e
JOIN app.universities u ON u.code = e.code
WHERE u.last_edited_by_user_id IS NULL
  AND NOT EXISTS (
    SELECT 1 FROM app.university_offerings o
    WHERE o.university_id = u.id AND o.study_level = 'undergraduate' AND o.last_edited_by_user_id IS NOT NULL
  )
ON CONFLICT (id) DO UPDATE SET
  field_value = EXCLUDED.field_value,
  source_url = EXCLUDED.source_url,
  source_section = EXCLUDED.source_section,
  extracted_quote = EXCLUDED.extracted_quote,
  verified_by = EXCLUDED.verified_by,
  status = EXCLUDED.status
WHERE (app.field_evidence.field_value, app.field_evidence.source_url, app.field_evidence.source_section,
       app.field_evidence.extracted_quote, app.field_evidence.verified_by, app.field_evidence.status)
  IS DISTINCT FROM (EXCLUDED.field_value, EXCLUDED.source_url, EXCLUDED.source_section,
       EXCLUDED.extracted_quote, EXCLUDED.verified_by, EXCLUDED.status);

-- Tỷ lệ ngoài [0, 1] là dữ liệu sai (UC-21): xóa giá trị cũ, trừ trường Moderator đã sửa tay.
UPDATE app.universities SET acceptance_rate = NULL
WHERE acceptance_rate IS NOT NULL AND (acceptance_rate < 0 OR acceptance_rate > 1)
  AND last_edited_by_user_id IS NULL;

DROP TABLE _refresh_evidence_241126;
DROP TABLE _refresh_media_241126;
DROP TABLE _refresh_scholarships_241126;
DROP TABLE _refresh_majors_241126;
DROP TABLE _refresh_school_241126;
